INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"03e64486-0331-5495-ae61-a7662b4d6554","title":"Mathematics · Grade 10 · Term 2 selection · Set B: Mixed revision","subject":"Mathematics","grade":"Grade 10","questions":[{"question":"A right triangle has opposite side 3 and hypotenuse 5 for angle θ. What is sin θ?","options":["5/3","3/4","3/5","4/5"],"correct_index":2,"explanation":"Sine is opposite divided by hypotenuse. Identify the sides relative to θ before choosing a ratio.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"R2 000 earns 8% simple interest each year for 3 years. Find the final amount.","options":["R2 160","R2 480","R2 519.42","R480"],"correct_index":1,"explanation":"Interest = 2 000 × 0.08 × 3 = R480. Add the original R2 000; R480 alone is only the interest.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Find the nth term of 5, 8, 11, 14, …","options":["3n + 2","5n + 3","3n + 5","2n + 3"],"correct_index":0,"explanation":"The common difference is 3, so use 3n + c. Setting n = 1 gives c = 2. Check n = 2 gives 8.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A cylinder has radius 3 cm and height 5 cm. Find its volume in terms of π.","options":["15π cm³","45π cm³","90π cm³","30π cm³"],"correct_index":1,"explanation":"Volume = πr²h = π × 3² × 5. Radius is squared; do not use the diameter as the radius.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A closed cube is enlarged until its volume is eight times the original. A learner says its surface area also becomes eight times as large. Which correction is justified?","options":["Lengths become eight times as large, so area doubles.","Lengths double, so surface area is unchanged.","Lengths double, so surface area becomes four times as large.","Lengths quadruple, so surface area doubles."],"correct_index":2,"explanation":"Volume scales with the cube of length: a factor of 8 means lengths double. Area scales with the square, giving a factor of 4, not 8.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","math"],"metadata":{"term":2,"focus":"Mixed revision: Trigonometry, statistics and growth; Measurement and number-pattern revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=ZX3jJwqKE2E%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=ZX3jJwqKE2E%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"1bde18d4-f19c-5705-8ecd-11c2c7bff18d","title":"Mathematics · Grade 10 · Term 3 selection · Set B: Mixed revision","subject":"Mathematics","grade":"Grade 10","questions":[{"question":"A triangle has angles 48° and 62°. Find its third angle.","options":["110°","70°","80°","132°"],"correct_index":1,"explanation":"Interior angles total 180°: 180 − 48 − 62 = 70°. State the angle-sum reason in a written solution.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Which point lies on y = x²?","options":["(−3; 9)","(−3; −9)","(2; 8)","(0; 1)"],"correct_index":0,"explanation":"Squaring means multiplying a number by itself: (−3)² = 9. The minus sign is inside the brackets.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Find the nth term of 5, 8, 11, 14, …","options":["3n + 2","5n + 3","3n + 5","2n + 3"],"correct_index":0,"explanation":"The common difference is 3, so use 3n + c. Setting n = 1 gives c = 2. Check n = 2 gives 8.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A cylinder has radius 3 cm and height 5 cm. Find its volume in terms of π.","options":["15π cm³","45π cm³","90π cm³","30π cm³"],"correct_index":1,"explanation":"Volume = πr²h = π × 3² × 5. Radius is squared; do not use the diameter as the radius.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A closed cube is enlarged until its volume is eight times the original. A learner says its surface area also becomes eight times as large. Which correction is justified?","options":["Lengths become eight times as large, so area doubles.","Lengths double, so surface area is unchanged.","Lengths double, so surface area becomes four times as large.","Lengths quadruple, so surface area doubles."],"correct_index":2,"explanation":"Volume scales with the cube of length: a factor of 8 means lengths double. Area scales with the square, giving a factor of 4, not 8.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","math"],"metadata":{"term":3,"focus":"Mixed revision: Geometry and functions; Measurement and number-pattern revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=ZX3jJwqKE2E%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=ZX3jJwqKE2E%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"e885eea8-154b-56ec-904a-2b2360645fce","title":"Mathematics · Grade 10 · Term 4 selection · Set B: Mixed revision","subject":"Mathematics","grade":"Grade 10","questions":[{"question":"A triangle has angles 48° and 62°. Find its third angle.","options":["110°","70°","80°","132°"],"correct_index":1,"explanation":"Interior angles total 180°: 180 − 48 − 62 = 70°. State the angle-sum reason in a written solution.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Which point lies on y = x²?","options":["(−3; 9)","(−3; −9)","(2; 8)","(0; 1)"],"correct_index":0,"explanation":"Squaring means multiplying a number by itself: (−3)² = 9. The minus sign is inside the brackets.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Find the median of 3, 7, 7, 10, 18.","options":["9","10","18","7"],"correct_index":3,"explanation":"The ordered list has five values; the third is the median. The mean would be 9, a different measure.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A bag has 3 red and 2 blue counters. One is chosen at random. P(blue) = ?","options":["2/5","3/5","1/2","2/3"],"correct_index":0,"explanation":"There are 2 blue outcomes out of 5 equally likely counters. Probability is favourable outcomes divided by total outcomes.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Five numbers have median 8 and mean 10. One number, 20, is replaced by 30 without changing the median. Which conclusion follows?","options":["Both measures increase by 10.","The mean stays 10; the median becomes 18.","The mean becomes 12; the median stays 8.","Both measures become 12."],"correct_index":2,"explanation":"The total increases by 10 while the count stays five, so the mean rises by 2. The stipulated unchanged median shows why the two averages respond differently.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","math"],"metadata":{"term":4,"focus":"Mixed revision: Geometry and functions; Trigonometry, statistics and growth","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=ZX3jJwqKE2E%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=ZX3jJwqKE2E%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"6f42acf6-398f-5028-9eb6-b9dbcc8e79ff","title":"Mathematical Literacy · Grade 10 · Term 2 selection · Set B: Mixed revision","subject":"Mathematical Literacy","grade":"Grade 10","questions":[{"question":"A learner earns R900 and spends R250 on transport and R400 on food. What remains?","options":["R650","R1 550","R350","R250"],"correct_index":3,"explanation":"Total spending = 250+400 = R650. Remaining money = income−spending = 900−650 = R250.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A product costs R80 and sells for R100. What is the profit?","options":["R180","R80","R20","R25"],"correct_index":2,"explanation":"Profit = selling price−cost price = R100−R80 = R20. This is the amount, not a percentage.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A class of 40 learners has 10 who walk to school. What angle represents them in a pie chart?","options":["25°","90°","100°","180°"],"correct_index":1,"explanation":"The fraction is 10/40 = ¼. Multiply by 360° to get 90°. The percentage 25% is not an angle.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A bar graph starts its vertical axis at 90 instead of 0. What should you check before comparing bars?","options":["Whether every bar becomes a percentage","Whether the data must be false","Whether the shortened scale exaggerates differences","Whether the units can be ignored"],"correct_index":2,"explanation":"A truncated axis can make small differences look large. Read the scale and values before drawing a conclusion.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}},{"question":"Two adverts show the same sales rising from 100 to 110. One graph begins at zero; the other at 99. Which judgement is sound?","options":["The second graph proves a 110% increase.","The first graph must conceal a fall.","Both can show correct values, but the second can exaggerate the visual increase.","Different axis starts necessarily mean different data."],"correct_index":2,"explanation":"The numerical increase is 10/100×100=10% in both. The shortened axis changes visual proportions, so read the actual scale before judging the adverts.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","matlit"],"metadata":{"term":2,"focus":"Mixed revision: Budgets, interest and floor plans; Data handling and year-end revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=68SQP-5M5pk%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=68SQP-5M5pk%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"f8a8b59b-8c86-5e3c-b7fd-3b72f1875b14","title":"Mathematical Literacy · Grade 10 · Term 3 selection · Set B: Mixed revision","subject":"Mathematical Literacy","grade":"Grade 10","questions":[{"question":"A bill charges R50 fixed plus R2 per kWh. What does 80 kWh cost?","options":["R160","R130","R210","R260"],"correct_index":2,"explanation":"Usage costs 80×R2 = R160. Add the fixed R50 once to get R210. A fixed charge is not multiplied by usage.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A spinner has 8 equal sectors; 3 are green. P(green) is…","options":["5/8","3/8","3/5","8/3"],"correct_index":1,"explanation":"Equal sectors give equally likely outcomes: 3 favourable sectors out of 8 total.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A class of 40 learners has 10 who walk to school. What angle represents them in a pie chart?","options":["25°","90°","100°","180°"],"correct_index":1,"explanation":"The fraction is 10/40 = ¼. Multiply by 360° to get 90°. The percentage 25% is not an angle.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A bar graph starts its vertical axis at 90 instead of 0. What should you check before comparing bars?","options":["Whether every bar becomes a percentage","Whether the data must be false","Whether the shortened scale exaggerates differences","Whether the units can be ignored"],"correct_index":2,"explanation":"A truncated axis can make small differences look large. Read the scale and values before drawing a conclusion.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}},{"question":"Two adverts show the same sales rising from 100 to 110. One graph begins at zero; the other at 99. Which judgement is sound?","options":["The second graph proves a 110% increase.","The first graph must conceal a fall.","Both can show correct values, but the second can exaggerate the visual increase.","Different axis starts necessarily mean different data."],"correct_index":2,"explanation":"The numerical increase is 10/100×100=10% in both. The shortened axis changes visual proportions, so read the actual scale before judging the adverts.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","matlit"],"metadata":{"term":3,"focus":"Mixed revision: Bills, units, scale and probability; Data handling and year-end revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=68SQP-5M5pk%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=68SQP-5M5pk%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"271227e8-f5ef-5255-8107-c804420fda78","title":"Mathematical Literacy · Grade 10 · Term 4 selection · Set B: Mixed revision","subject":"Mathematical Literacy","grade":"Grade 10","questions":[{"question":"A bill charges R50 fixed plus R2 per kWh. What does 80 kWh cost?","options":["R160","R130","R210","R260"],"correct_index":2,"explanation":"Usage costs 80×R2 = R160. Add the fixed R50 once to get R210. A fixed charge is not multiplied by usage.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A spinner has 8 equal sectors; 3 are green. P(green) is…","options":["5/8","3/8","3/5","8/3"],"correct_index":1,"explanation":"Equal sectors give equally likely outcomes: 3 favourable sectors out of 8 total.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A savings example uses 5% simple annual interest on R1 200 for one year. Find the interest.","options":["R60","R1 260","R600","R6"],"correct_index":0,"explanation":"5% means 0.05. Interest = 1 200×0.05 = R60; R1 260 includes the original savings.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A rectangular room is 4 m by 3 m. Find its floor area.","options":["14 m²","12 m²","7 m²","24 m²"],"correct_index":1,"explanation":"Area = length×width = 4×3 = 12 m². 14 m is its perimeter, a length rather than an area.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A learner has R900 income and R650 necessary expenses. A savings goal is R300. Which plan meets it without borrowing?","options":["Keep expenses at R650 and save R300.","Increase expenses by R50 to reach the goal.","Reduce expenses by R50, leaving R300 to save.","Save the R900 and ignore expenses."],"correct_index":2,"explanation":"Current surplus is R250, R50 below the goal. Expenses must fall to R600 or income rise by R50; savings cannot exceed the money left after expenses.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","matlit"],"metadata":{"term":4,"focus":"Mixed revision: Bills, units, scale and probability; Budgets, interest and floor plans","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=68SQP-5M5pk%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=68SQP-5M5pk%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"c3bc8393-78ee-531b-8265-25b68953648e","title":"Physical Sciences · Grade 10 · Term 2 selection · Set B: Mixed revision","subject":"Physical Sciences","grade":"Grade 10","questions":[{"question":"A learner walks 6 m east then 2 m west. Find the displacement.","options":["4 m east","8 m east","4 m west","8 m west"],"correct_index":0,"explanation":"Take east positive: +6−2=+4 m. Total distance is 8 m, but displacement includes direction and endpoints.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"Balance H₂ + O₂ → H₂O using the smallest whole-number coefficients.","options":["1, 1, 1","1, 2, 1","2, 2, 1","2, 1, 2"],"correct_index":3,"explanation":"2H₂+O₂→2H₂O has 4 hydrogen and 2 oxygen atoms on both sides. Change coefficients, not chemical subscripts.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"How many particles are in 0.5 mol? Use Nₐ = 6.02 × 10²³ mol⁻¹.","options":["1.204 × 10²⁴","6.02 × 10²³","3.01 × 10²³","0.83 × 10⁻²³"],"correct_index":2,"explanation":"N=nNₐ = 0.5×6.02×10²³. Half a mole contains half Avogadro's number of particles.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"An object starts from rest with constant acceleration 2 m·s⁻² for 3 s. Find its displacement.","options":["6 m","18 m","3 m","9 m"],"correct_index":3,"explanation":"Δx=uΔt+½aΔt²=0+½×2×3²=9 m. Include the square on time.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"Two identical balls move at speeds v and 2v. A learner claims the second has twice the kinetic energy. Which correction is justified?","options":["It has the same energy because masses are equal.","It has half the energy because speed is greater.","It has four times the kinetic energy because energy depends on v².","It has eight times the energy because speed is cubed."],"correct_index":2,"explanation":"For equal masses, Eₖ=½mv² gives an energy ratio (2v)²/v²=4. Comparing the proportional relationship reveals the error without needing a numerical mass.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","phsc"],"metadata":{"term":2,"focus":"Mixed revision: Motion and chemical equations; Chemical quantities and mechanics revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mQ_5vFi9Voc%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=mQ_5vFi9Voc%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"01e8c633-7f85-51f8-9505-de763882395a","title":"Physical Sciences · Grade 10 · Term 3 selection · Set B: Mixed revision","subject":"Physical Sciences","grade":"Grade 10","questions":[{"question":"A charge of 12 C passes a point in 4 s. Find the current.","options":["48 A","0.33 A","8 A","3 A"],"correct_index":3,"explanation":"Current is charge per unit time: I=Q/Δt=12/4=3 A. Coulombs and seconds are not added.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"Which statement describes isotopes of the same element?","options":["Different proton numbers, same element","Same mass number in every isotope","Same proton number, different neutron number","Different proton and electron numbers by definition"],"correct_index":2,"explanation":"The proton number identifies the element. Isotopes differ in neutrons and therefore in mass number.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"How many particles are in 0.5 mol? Use Nₐ = 6.02 × 10²³ mol⁻¹.","options":["1.204 × 10²⁴","6.02 × 10²³","3.01 × 10²³","0.83 × 10⁻²³"],"correct_index":2,"explanation":"N=nNₐ = 0.5×6.02×10²³. Half a mole contains half Avogadro's number of particles.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"An object starts from rest with constant acceleration 2 m·s⁻² for 3 s. Find its displacement.","options":["6 m","18 m","3 m","9 m"],"correct_index":3,"explanation":"Δx=uΔt+½aΔt²=0+½×2×3²=9 m. Include the square on time.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"Two identical balls move at speeds v and 2v. A learner claims the second has twice the kinetic energy. Which correction is justified?","options":["It has the same energy because masses are equal.","It has half the energy because speed is greater.","It has four times the kinetic energy because energy depends on v².","It has eight times the energy because speed is cubed."],"correct_index":2,"explanation":"For equal masses, Eₖ=½mv² gives an energy ratio (2v)²/v²=4. Comparing the proportional relationship reveals the error without needing a numerical mass.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","phsc"],"metadata":{"term":3,"focus":"Mixed revision: Electric circuits and atomic structure; Chemical quantities and mechanics revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mQ_5vFi9Voc%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=mQ_5vFi9Voc%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"10b722f7-06e6-56ba-ac8d-fd9d2acb7989","title":"Physical Sciences · Grade 10 · Term 4 selection · Set B: Mixed revision","subject":"Physical Sciences","grade":"Grade 10","questions":[{"question":"A charge of 12 C passes a point in 4 s. Find the current.","options":["48 A","0.33 A","8 A","3 A"],"correct_index":3,"explanation":"Current is charge per unit time: I=Q/Δt=12/4=3 A. Coulombs and seconds are not added.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"Which statement describes isotopes of the same element?","options":["Different proton numbers, same element","Same mass number in every isotope","Same proton number, different neutron number","Different proton and electron numbers by definition"],"correct_index":2,"explanation":"The proton number identifies the element. Isotopes differ in neutrons and therefore in mass number.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"A car's speed increases from 5 m·s⁻¹ to 17 m·s⁻¹ in 4 s. Find its acceleration.","options":["5.5 m·s⁻²","3 m·s⁻²","48 m·s⁻²","12 m·s⁻²"],"correct_index":1,"explanation":"a=(v−u)/Δt=(17−5)/4=3 m·s⁻². Divide the change in velocity, not the final velocity, by time.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"An object moves at constant velocity 8 m·s⁻¹ for 6 s. Find its displacement.","options":["14 m","1.33 m","48 m","2 m"],"correct_index":2,"explanation":"At constant velocity, Δx=vΔt=8×6=48 m. Acceleration is zero but displacement need not be zero.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"A trolley travels east at constant velocity. A learner concludes no forces act on it. Which evaluation is correct?","options":["Every force must be zero because velocity is constant.","The net force must point east because it is moving east.","The net force is zero; individual balanced forces may still act.","Gravity disappears whenever horizontal speed is constant."],"correct_index":2,"explanation":"Constant velocity implies zero acceleration and therefore zero resultant force. Weight and normal force, for example, can act and balance; zero resultant is not absence of forces.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","phsc"],"metadata":{"term":4,"focus":"Mixed revision: Electric circuits and atomic structure; Motion and chemical equations","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mQ_5vFi9Voc%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=mQ_5vFi9Voc%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"b5a302c7-fa69-57c3-b777-3d95623d2635","title":"Life Sciences · Grade 10 · Term 2 selection · Set B: Mixed revision","subject":"Life Sciences","grade":"Grade 10","questions":[{"question":"In grass → grasshopper → frog, what is the grasshopper?","options":["A producer","A primary consumer","A secondary consumer","A decomposer by definition"],"correct_index":1,"explanation":"Grass is the producer. The grasshopper eats the producer, so it is the primary consumer; the frog is a secondary consumer.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"Which scientific name is correctly written in plain text?","options":["Homo sapiens","homo Sapiens","HOMO SAPIENS","Homo Sapiens"],"correct_index":0,"explanation":"The genus begins with a capital and the species epithet with lowercase. In formatted writing both are italicised, or separately underlined when handwritten.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"Why are fungi not classified as plants?","options":["They all move using legs","They all lack cell walls","They are all bacteria","They obtain organic nutrients rather than photosynthesising like green plants"],"correct_index":3,"explanation":"Fungi are heterotrophs and absorb nutrients. Their cell walls typically contain chitin, rather than the cellulose characteristic of plants.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"Which feature is shared by plants and animals?","options":["Their cells have membrane-bound nuclei","They both have chloroplasts in every cell","They both have cellulose cell walls","They are all unicellular"],"correct_index":0,"explanation":"Plants and animals are eukaryotes with membrane-bound nuclei. Animal cells do not have chloroplasts or cellulose walls.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"A culture of microorganisms grows on dead plant material. A learner calls all of them harmful. Which evaluation is best?","options":["Growth on dead material proves every organism causes human disease.","Anything too small to see has no ecological role.","Decomposition may recycle nutrients; identify organisms and effects before classifying harm.","Microorganisms are always beneficial and never pathogenic."],"correct_index":2,"explanation":"Microorganisms have diverse roles, including decomposition and disease. The observed nutrient-recycling activity does not support an unrestricted claim that all are harmful.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","lisc"],"metadata":{"term":2,"focus":"Mixed revision: Ecosystems, fossils and classification; Biodiversity and year-end consolidation","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=8hlSLsoZ3b0%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=8hlSLsoZ3b0%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"6b730bee-a43b-5737-8cd7-e62248824156","title":"Life Sciences · Grade 10 · Term 3 selection · Set B: Mixed revision","subject":"Life Sciences","grade":"Grade 10","questions":[{"question":"Which tissue transports most water and mineral salts from roots towards leaves?","options":["Xylem","Phloem","Epidermis only","Palisade mesophyll"],"correct_index":0,"explanation":"Xylem vessels provide a transport pathway for water and dissolved minerals. Phloem mainly transports organic nutrients such as sucrose.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"Why is a red blood cell's biconcave shape useful?","options":["It makes the cell a rigid cube","It produces antibodies","It stops oxygen diffusion","It gives a large surface area relative to volume for gas exchange"],"correct_index":3,"explanation":"The shape supports rapid gas exchange over a short diffusion distance. Haemoglobin within the cell binds oxygen.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"Why are fungi not classified as plants?","options":["They all move using legs","They all lack cell walls","They are all bacteria","They obtain organic nutrients rather than photosynthesising like green plants"],"correct_index":3,"explanation":"Fungi are heterotrophs and absorb nutrients. Their cell walls typically contain chitin, rather than the cellulose characteristic of plants.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"Which feature is shared by plants and animals?","options":["Their cells have membrane-bound nuclei","They both have chloroplasts in every cell","They both have cellulose cell walls","They are all unicellular"],"correct_index":0,"explanation":"Plants and animals are eukaryotes with membrane-bound nuclei. Animal cells do not have chloroplasts or cellulose walls.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"A culture of microorganisms grows on dead plant material. A learner calls all of them harmful. Which evaluation is best?","options":["Growth on dead material proves every organism causes human disease.","Anything too small to see has no ecological role.","Decomposition may recycle nutrients; identify organisms and effects before classifying harm.","Microorganisms are always beneficial and never pathogenic."],"correct_index":2,"explanation":"Microorganisms have diverse roles, including decomposition and disease. The observed nutrient-recycling activity does not support an unrestricted claim that all are harmful.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","lisc"],"metadata":{"term":3,"focus":"Mixed revision: Plant transport and animal circulation; Biodiversity and year-end consolidation","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=8hlSLsoZ3b0%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=8hlSLsoZ3b0%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"8a670620-72fc-5d7f-9e3d-f408cc2bb165","title":"Life Sciences · Grade 10 · Term 4 selection · Set B: Mixed revision","subject":"Life Sciences","grade":"Grade 10","questions":[{"question":"Which tissue transports most water and mineral salts from roots towards leaves?","options":["Xylem","Phloem","Epidermis only","Palisade mesophyll"],"correct_index":0,"explanation":"Xylem vessels provide a transport pathway for water and dissolved minerals. Phloem mainly transports organic nutrients such as sucrose.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"Why is a red blood cell's biconcave shape useful?","options":["It makes the cell a rigid cube","It produces antibodies","It stops oxygen diffusion","It gives a large surface area relative to volume for gas exchange"],"correct_index":3,"explanation":"The shape supports rapid gas exchange over a short diffusion distance. Haemoglobin within the cell binds oxygen.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"Which is an abiotic factor in a pond?","options":["Algae","Fish","Water temperature","Bacteria"],"correct_index":2,"explanation":"Abiotic factors are non-living physical or chemical conditions. Living organisms are biotic factors.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"Why are fossils useful when studying life's history?","options":["They prove every past organism was preserved","They show all species existed at the same time","They cannot be compared with living organisms","They provide evidence of organisms and environments from the past"],"correct_index":3,"explanation":"The fossil record documents past life and changes through time, but preservation is incomplete and biased towards suitable conditions.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"Frogs decline after a pesticide is introduced near a pond. Which evidence best tests whether the pesticide contributed?","options":["A photograph of one frog before spraying.","The assumption that every population change has a single cause.","Repeated frog counts and exposure measurements at treated and comparable untreated ponds.","Counts only at the treated pond on one day."],"correct_index":2,"explanation":"Comparison sites and repeated exposure and population measurements help separate pesticide effects from weather, habitat change and natural variation. Timing alone is insufficient causal evidence.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","lisc"],"metadata":{"term":4,"focus":"Mixed revision: Plant transport and animal circulation; Ecosystems, fossils and classification","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=8hlSLsoZ3b0%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=8hlSLsoZ3b0%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"0d2b4837-299f-5802-8227-7fe725b9139c","title":"Accounting · Grade 10 · Term 2 selection · Set B: Mixed revision","subject":"Accounting","grade":"Grade 10","questions":[{"question":"Sales are R80 000 and cost of sales R50 000. Find gross profit.","options":["R130 000","R50 000","R30 000","R80 000"],"correct_index":2,"explanation":"Gross profit = sales−cost of sales = R30 000. Operating expenses are deducted later when calculating net profit.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Current assets total R60 000 and current liabilities R30 000. Find the current ratio.","options":["1:2","2:1","3:1","1:1"],"correct_index":1,"explanation":"Current ratio = current assets/current liabilities = 60 000/30 000 = 2:1. It is one indicator of short-term liquidity, not a guarantee of solvency.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Direct materials cost R8 000 and direct labour R5 000. Find prime cost.","options":["R13 000","R3 000","R40 000","R8 000"],"correct_index":0,"explanation":"Prime cost = direct materials + direct labour = R13 000. Factory overheads are added separately for total production cost.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A cash budget opens with R4 000, receives R9 000 and pays R10 000. Find its closing balance.","options":["R5 000","R3 000","R23 000","−R1 000"],"correct_index":1,"explanation":"Closing cash = opening cash+receipts−payments = 4 000+9 000−10 000 = R3 000. Opening cash must be included.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A cash budget shows a R3 000 closing balance after excluding depreciation of R1 000. A learner deducts depreciation again. Which judgement is correct?","options":["Reduce cash to R2 000 because every expense is a payment.","Increase cash to R4 000 because depreciation creates cash.","Keep R3 000; depreciation is not a cash payment in this budget.","Treat depreciation as a receipt from customers."],"correct_index":2,"explanation":"Depreciation allocates an asset's cost as an expense without a current cash outflow. Deducting it in a cash budget would understate cash; actual asset purchases are considered separately.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","acc"],"metadata":{"term":2,"focus":"Mixed revision: Financial statements and indicators; Manufacturing costs and budgets","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=xMiwoYjt1vw%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=xMiwoYjt1vw%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"b65581de-887e-53f7-911d-b19ae9b8dc0e","title":"Accounting · Grade 10 · Term 3 selection · Set B: Mixed revision","subject":"Accounting","grade":"Grade 10","questions":[{"question":"A business buys trading stock on credit. Which journal usually records this purchase?","options":["Cash receipts journal","Creditors journal","Debtors journal","Cash payments journal"],"correct_index":1,"explanation":"A credit purchase of stock from a supplier belongs in the creditors journal. No cash moves at purchase, so a cash journal is inappropriate.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Equipment costing R20 000 depreciates at 10% per year on cost. Find one full year's depreciation.","options":["R2 000","R18 000","R200","R22 000"],"correct_index":0,"explanation":"Depreciation = cost×rate×time = 20 000×0.10×1 = R2 000. R18 000 is the carrying value after this charge.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Direct materials cost R8 000 and direct labour R5 000. Find prime cost.","options":["R13 000","R3 000","R40 000","R8 000"],"correct_index":0,"explanation":"Prime cost = direct materials + direct labour = R13 000. Factory overheads are added separately for total production cost.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A cash budget opens with R4 000, receives R9 000 and pays R10 000. Find its closing balance.","options":["R5 000","R3 000","R23 000","−R1 000"],"correct_index":1,"explanation":"Closing cash = opening cash+receipts−payments = 4 000+9 000−10 000 = R3 000. Opening cash must be included.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A cash budget shows a R3 000 closing balance after excluding depreciation of R1 000. A learner deducts depreciation again. Which judgement is correct?","options":["Reduce cash to R2 000 because every expense is a payment.","Increase cash to R4 000 because depreciation creates cash.","Keep R3 000; depreciation is not a cash payment in this budget.","Treat depreciation as a receipt from customers."],"correct_index":2,"explanation":"Depreciation allocates an asset's cost as an expense without a current cash outflow. Deducting it in a cash budget would understate cash; actual asset purchases are considered separately.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","acc"],"metadata":{"term":3,"focus":"Mixed revision: Journals, payroll and adjustments; Manufacturing costs and budgets","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=xMiwoYjt1vw%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=xMiwoYjt1vw%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"c4402bf0-2a50-5d89-b89e-365d5862d999","title":"Accounting · Grade 10 · Term 4 selection · Set B: Mixed revision","subject":"Accounting","grade":"Grade 10","questions":[{"question":"A business buys trading stock on credit. Which journal usually records this purchase?","options":["Cash receipts journal","Creditors journal","Debtors journal","Cash payments journal"],"correct_index":1,"explanation":"A credit purchase of stock from a supplier belongs in the creditors journal. No cash moves at purchase, so a cash journal is inappropriate.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Equipment costing R20 000 depreciates at 10% per year on cost. Find one full year's depreciation.","options":["R2 000","R18 000","R200","R22 000"],"correct_index":0,"explanation":"Depreciation = cost×rate×time = 20 000×0.10×1 = R2 000. R18 000 is the carrying value after this charge.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Gross profit is R30 000 and sales R80 000. Find gross profit as a percentage of sales.","options":["60%","62.5%","266.7%","37.5%"],"correct_index":3,"explanation":"30 000/80 000×100 = 37.5%. A percentage of cost of sales would have a different denominator.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Rent of R1 000 is owed for the current year but unpaid at year end. What adjustment is needed?","options":["Increase rent expense and recognise an accrued-expense liability","Decrease rent expense and create an asset","Record no expense until payment","Increase bank immediately"],"correct_index":0,"explanation":"Accrual accounting records the expense in the period incurred. The unpaid amount creates a liability.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A business has current assets R60 000, including R45 000 slow-moving stock, and current liabilities R30 000. Why is its 2:1 current ratio insufficient reassurance?","options":["A 2:1 ratio guarantees every debt can be paid immediately.","Stock is always equivalent to cash on demand.","Only R15 000 of current assets excludes stock, so near-term cash needs require further investigation.","Current liabilities must be zero whenever current assets are larger."],"correct_index":2,"explanation":"The current ratio includes inventory, which may not sell promptly. Excluding stock gives 15 000/30 000=0.5:1; investigate collections, stock movement and payment timing before judging liquidity.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","acc"],"metadata":{"term":4,"focus":"Mixed revision: Journals, payroll and adjustments; Financial statements and indicators","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=xMiwoYjt1vw%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=xMiwoYjt1vw%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}}]$smartbridge$::jsonb)
